import base64
import hashlib
import os
import secrets
import urllib.parse
from dataclasses import dataclass
from typing import Any, Dict, Optional

import requests


@dataclass
class PKCEAuthResult:
    authorization_url: str
    state: str
    code_verifier: str


class Auth0PKCEClient:
    def __init__(
        self,
        domain: Optional[str] = None,
        client_id: Optional[str] = None,
        redirect_uri: Optional[str] = None,
        audience: Optional[str] = None,
        scope: str = "openid profile email",
    ):
        self.domain = (domain or os.environ.get("AUTH0_DOMAIN") or "").strip()
        self.client_id = (client_id or os.environ.get("AUTH0_CLIENT_ID") or "").strip()
        self.redirect_uri = redirect_uri or os.environ.get("AUTH0_REDIRECT_URI") or ""
        self.audience = audience or os.environ.get("AUTH0_AUDIENCE")
        self.scope = scope

        if not self.domain:
            raise ValueError("AUTH0_DOMAIN is required")
        if not self.client_id:
            raise ValueError("AUTH0_CLIENT_ID is required")
        if not self.redirect_uri:
            raise ValueError("AUTH0_REDIRECT_URI is required")

        self._authorize_endpoint = f"https://{self.domain}/authorize"
        self._token_endpoint = f"https://{self.domain}/oauth/token"
        self._userinfo_endpoint = f"https://{self.domain}/userinfo"

    @staticmethod
    def _b64url(data: bytes) -> str:
        return base64.urlsafe_b64encode(data).rstrip(b"=").decode("ascii")

    @staticmethod
    def _code_challenge(code_verifier: str) -> str:
        digest = hashlib.sha256(code_verifier.encode("ascii")).digest()
        return Auth0PKCEClient._b64url(digest)

    def create_login_request(self, state: Optional[str] = None) -> PKCEAuthResult:
        code_verifier = self._b64url(secrets.token_bytes(32))
        state = state or self._b64url(secrets.token_bytes(16))
        code_challenge = self._code_challenge(code_verifier)

        params = {
            "response_type": "code",
            "client_id": self.client_id,
            "redirect_uri": self.redirect_uri,
            "scope": self.scope,
            "state": state,
            "code_challenge": code_challenge,
            "code_challenge_method": "S256",
        }
        if self.audience:
            params["audience"] = self.audience

        authorization_url = f"{self._authorize_endpoint}?{urllib.parse.urlencode(params)}"
        return PKCEAuthResult(
            authorization_url=authorization_url,
            state=state,
            code_verifier=code_verifier,
        )

    def exchange_code_for_tokens(self, code: str, code_verifier: str) -> Dict[str, Any]:
        payload = {
            "grant_type": "authorization_code",
            "client_id": self.client_id,
            "code": code,
            "redirect_uri": self.redirect_uri,
            "code_verifier": code_verifier,
        }
        if os.environ.get("AUTH0_CLIENT_SECRET"):
            payload["client_secret"] = os.environ["AUTH0_CLIENT_SECRET"]

        resp = requests.post(
            self._token_endpoint,
            json=payload,
            timeout=30,
            headers={"Content-Type": "application/json"},
        )
        resp.raise_for_status()
        return resp.json()

    def fetch_userinfo(self, access_token: str) -> Dict[str, Any]:
        resp = requests.get(
            self._userinfo_endpoint,
            headers={"Authorization": f"Bearer {access_token}"},
            timeout=30,
        )
        resp.raise_for_status()
        return resp.json()

    def handle_callback(
        self,
        query_params: Dict[str, str],
        expected_state: str,
        code_verifier: str,
    ) -> Dict[str, Any]:
        error = query_params.get("error")
        if error:
            raise RuntimeError(
                f"Authorization failed: {error}: {query_params.get('error_description', '')}".strip()
            )

        state = query_params.get("state")
        if not state or state != expected_state:
            raise ValueError("Invalid or missing state parameter")

        code = query_params.get("code")
        if not code:
            raise ValueError("Missing authorization code")

        tokens = self.exchange_code_for_tokens(code=code, code_verifier=code_verifier)
        access_token = tokens.get("access_token")
        if not access_token:
            return tokens

        try:
            tokens["userinfo"] = self.fetch_userinfo(access_token)
        except requests.RequestException:
            tokens["userinfo"] = None
        return tokens
